_theme.customCss:
@import url('https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap');

/* =========================================
   1. 基础画板 & 前景图层
   ========================================= */
.xt-root {
    background-image: url('https://imgbed.heliar.top/i/EHj6SLJySjzaCzHU_IMG_4087.jpeg') !important;
    background-size: 100% 100% !important; width: 100% !important; aspect-ratio: 1080 / 1920 !important; 
    position: relative !important; padding: 0 !important; border: none !important; box-shadow: none !important;
    background-color: transparent !important; overflow: hidden !important; border-radius: 0 !important; 
}
.xt-root::after {
    content: "" !important; position: absolute !important; top: 0 !important; left: 0 !important;
    width: 100% !important; height: 100% !important;
    background-image: url('https://imgbed.heliar.top/i/wGvIdq9kwHs7Gzpu_IMG_2551.png') !important;
    background-size: 100% 100% !important; z-index: 999 !important; pointer-events: none !important; 
}
.xt-root, .xt-root * { font-family: 'ZCOOL KuaiLe', 'Comic Sans MS', cursive, sans-serif !important; }
.xt-content, .xt-section, .xt-section-body { background: transparent !important; border: none !important; box-shadow: none !important; padding: 0 !important; margin: 0 !important; }

/* =========================================
   2. 中间层文字：日记 & 备忘录
   ========================================= */
.xt-text-cuteDiary {
    position: absolute !important; top: 30% !important; left: 4% !important; width: 65% !important; height: 25% !important; 
    z-index: 10 !important; color: #4a362c !important; font-size: 16px !important; line-height: 1.8 !important; 
    background: transparent !important; border: none !important; text-indent: 2em !important; 
    overflow-y: auto !important; overflow-x: hidden !important; padding-right: 5px !important; 
}
.xt-text-cuteDiary::-webkit-scrollbar { display: none !important; width: 0 !important; }

.xt-section {
    position: absolute !important; top: 79% !important; left: 47% !important; width: 38% !important; height: 15% !important; 
    z-index: 10 !important; overflow-y: auto !important; overflow-x: hidden !important;
}
.xt-section::-webkit-scrollbar { display: none !important; width: 0 !important; }
.xt-section-title { color: #4a362c !important; font-size: 16px !important; font-weight: bold !important; margin-bottom: 4px !important; background: transparent !important; border: none !important; }
.xt-section-body > * { color: #4a362c !important; font-size: 16px !important; line-height: 1.8 !important; padding: 0 !important; margin: 0 !important; background: transparent !important; border: none !important; }

/* =========================================
   🎁 3. 彩蛋一：方形苹果切片 (喷射 Emoji)
   ========================================= */
.xt-action-1, .xt-action-1 + .xt-spacer {
    display: block !important; position: absolute !important;
    top: 59% !important; left: 77% !important; width: 16% !important; height: 14% !important;  
    background: transparent !important; border: none !important; z-index: 1010 !important; 
}
.xt-action-1 { cursor: pointer !important; }
.xt-action-1 + .xt-spacer { pointer-events: none !important; }
.xt-action-1:active { background: radial-gradient(ellipse at center, rgba(255,255,255,0.7) 0%, rgba(255,255,255,0) 70%) !important; border-radius: 15px !important; }

.xt-action-1::before, .xt-action-1::after, .xt-action-1 + .xt-spacer::before, .xt-action-1 + .xt-spacer::after { position: absolute; top: 30%; left: 30%; font-size: 32px; opacity: 0; pointer-events: none; z-index: 1011; }
.xt-action-1::before { content: "🥺"; } .xt-action-1::after { content: "🥰"; }
.xt-action-1 + .xt-spacer::before { content: "❤️"; } .xt-action-1 + .xt-spacer::after { content: "😚"; }

@keyframes pop1 { 0% { opacity: 0; transform: translate(0,0) scale(0.5); } 20% { opacity: 1; transform: translate(-20px, -40px) scale(1.2) rotate(-15deg); } 80% { opacity: 1; transform: translate(-40px, -100px) scale(1) rotate(-15deg); } 100% { opacity: 0; transform: translate(-40px, -120px) scale(0.8) rotate(-15deg); } }
@keyframes pop2 { 0% { opacity: 0; transform: translate(0,0) scale(0.5); } 20% { opacity: 1; transform: translate(20px, -50px) scale(1.2) rotate(15deg); } 80% { opacity: 1; transform: translate(50px, -120px) scale(1) rotate(25deg); } 100% { opacity: 0; transform: translate(50px, -140px) scale(0.8) rotate(25deg); } }
@keyframes pop3 { 0% { opacity: 0; transform: translate(0,0) scale(0.5); } 20% { opacity: 1; transform: translate(-10px, -60px) scale(1.2) rotate(-5deg); } 80% { opacity: 1; transform: translate(-15px, -140px) scale(1) rotate(-10deg); } 100% { opacity: 0; transform: translate(-15px, -160px) scale(0.8) rotate(-10deg); } }
@keyframes pop4 { 0% { opacity: 0; transform: translate(0,0) scale(0.5); } 20% { opacity: 1; transform: translate(10px, -45px) scale(1.2) rotate(5deg); } 80% { opacity: 1; transform: translate(30px, -110px) scale(1) rotate(10deg); } 100% { opacity: 0; transform: translate(30px, -130px) scale(0.8) rotate(10deg); } }

#xt-t1:checked ~ .xt-content .xt-action-1::before { animation: pop1 1s ease-out forwards; }
#xt-t1:checked ~ .xt-content .xt-action-1::after  { animation: pop2 1s ease-out 0.1s forwards; }
#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-spacer::before { animation: pop3 1s ease-out 0.2s forwards; }
#xt-t1:checked ~ .xt-content .xt-action-1 + .xt-spacer::after  { animation: pop4 1s ease-out 0.15s forwards; }

/* =========================================
   🎊 4. 彩蛋二：MENU 喷射贴纸
   ========================================= */
.xt-action-2, .xt-action-2 + .xt-spacer {
    display: block !important; position: absolute !important; top: 2% !important; left: 15% !important; width: 70% !important; height: 14% !important;  
    background: transparent !important; border: none !important; z-index: 1001 !important; cursor: pointer !important;
}
.xt-action-2 + .xt-spacer { pointer-events: none !important; }
.xt-action-2:active { background: radial-gradient(ellipse at center, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0) 75%) !important; }
.xt-action-2::before, .xt-action-2::after, .xt-action-2 + .xt-spacer::before, .xt-action-2 + .xt-spacer::after {
    content: "" !important; position: absolute; top: 50%; width: 45px; height: 45px;
    background-image: url('https://imgbed.heliar.top/i/_PW80d4RjaIzGaUA_IMG_2621.png'); background-size: contain; background-repeat: no-repeat; opacity: 0; pointer-events: none; z-index: 1002;
}
.xt-action-2::before { left: 10%; } .xt-action-2 + .xt-spacer::before { left: 20%; width: 35px; height: 35px; }
.xt-action-2::after { right: 10%; left: auto; } .xt-action-2 + .xt-spacer::after { right: 20%; left: auto; width: 35px; height: 35px; }

@keyframes sprayImgLL { 0% { opacity: 0; transform: translate(0,0) scale(0.5) rotate(0deg); } 20% { opacity: 1; transform: translate(-30px, -40px) scale(1.2) rotate(-45deg); } 80% { opacity: 1; transform: translate(-80px, 60px) scale(1) rotate(-180deg); } 100% { opacity: 0; transform: translate(-90px, 80px) scale(0.8) rotate(-220deg); } }
@keyframes sprayImgLR { 0% { opacity: 0; transform: translate(0,0) scale(0.5) rotate(0deg); } 20% { opacity: 1; transform: translate(-15px, -60px) scale(1.2) rotate(45deg); } 80% { opacity: 1; transform: translate(-40px, 40px) scale(1) rotate(180deg); } 100% { opacity: 0; transform: translate(-50px, 60px) scale(0.8) rotate(220deg); } }
@keyframes sprayImgRL { 0% { opacity: 0; transform: translate(0,0) scale(0.5) rotate(0deg); } 20% { opacity: 1; transform: translate(15px, -60px) scale(1.2) rotate(-45deg); } 80% { opacity: 1; transform: translate(40px, 40px) scale(1) rotate(-180deg); } 100% { opacity: 0; transform: translate(50px, 60px) scale(0.8) rotate(-220deg); } }
@keyframes sprayImgRR { 0% { opacity: 0; transform: translate(0,0) scale(0.5) rotate(0deg); } 20% { opacity: 1; transform: translate(30px, -40px) scale(1.2) rotate(45deg); } 80% { opacity: 1; transform: translate(80px, 60px) scale(1) rotate(180deg); } 100% { opacity: 0; transform: translate(90px, 80px) scale(0.8) rotate(220deg); } }

#xt-t2:checked ~ .xt-content .xt-action-2::before { animation: sprayImgLL 1.2s ease-out forwards; }
#xt-t2:checked ~ .xt-content .xt-action-2 + .xt-spacer::before { animation: sprayImgLR 1.2s ease-out 0.1s forwards; }
#xt-t2:checked ~ .xt-content .xt-action-2::after { animation: sprayImgRR 1.2s ease-out forwards; }
#xt-t2:checked ~ .xt-content .xt-action-2 + .xt-spacer::after { animation: sprayImgRL 1.2s ease-out 0.1s forwards; }

/* =========================================
   🍎 5. 彩蛋三：苹果小厨房菜单浮窗
   ========================================= */
.xt-action-3 {
    display: block !important; position: absolute !important; top: 55% !important; left: 5% !important; width: 40% !important; height: 22% !important;  
    background: transparent !important; border: none !important; z-index: 1001 !important; cursor: pointer !important;
}
.xt-action-3:active { background: radial-gradient(ellipse at center, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0) 70%) !important; }

.xt-action-3 + .xt-spacer {
    display: block !important; position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
    background-color: rgba(255, 249, 240, 0.85) !important; backdrop-filter: blur(4px) !important; 
    background-image: url('https://imgbed.heliar.top/i/FNyKPCALdrGqaat7_IMG_2561.png') !important; background-size: 100% 100% !important;
    z-index: 2000 !important; opacity: 0 !important; pointer-events: none !important; transform: scale(0.95) !important; transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}

.xt-text-todaySpecial {
    position: absolute !important; 
    top: 27% !important; 
    left: 25% !important; 
    width: 70% !important; 
    height: auto !important; min-height: 15% !important; max-height: 45% !important;

    z-index: 2001 !important; opacity: 0 !important; pointer-events: none !important; 
    transform-origin: center !important; transform: scale(0.95) !important; transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
    color: #4a362c !important; font-size: 16px !important; line-height: 1.8 !important; text-align: center !important; font-weight: bold !important;
    display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important;
    background: #fff !important; border: 4px solid #f29c9f !important; border-radius: 25px 20px 25px 20px !important; padding: 20px 15px !important; box-shadow: 0 8px 20px rgba(242, 156, 159, 0.3) !important; overflow-y: auto !important;

    /* 👇 开启换行魔法：识别 \n 并自动换行 */
    white-space: pre-wrap !important; 
}

/* 👇 新增：今日食谱的固定标题 */
.xt-text-todaySpecial::before {
    content: "今日食谱" !important;
    color: #d93c39 !important;
    font-size: 18px !important;
    margin-bottom: 12px !important;
    padding-bottom: 8px !important;
    border-bottom: 2px dashed #f29c9f !important;
    width: 90% !important;
    display: block !important;
}

.xt-text-todaySpecial::-webkit-scrollbar { display: none !important; width: 0 !important; }

#xt-t3:checked ~ .xt-content .xt-action-3 + .xt-spacer { opacity: 1 !important; transform: scale(1) !important; }
#xt-t3:checked ~ .xt-content .xt-text-todaySpecial { opacity: 1 !important; transform: scale(1) !important; }
#xt-t3:checked ~ .xt-content .xt-action-3 { top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2005 !important; background: transparent !important; }

/* =========================================
   💬 6. 彩蛋四：备忘录心里话浮窗
   ========================================= */
.xt-action-4 {
    display: block !important; position: absolute !important; top: 80% !important; left: 10% !important; width: 30% !important; height: 20% !important;  
    background: transparent !important; border: none !important; z-index: 1001 !important; cursor: pointer !important;
}
.xt-action-4:active { background: radial-gradient(ellipse at center, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0) 70%) !important; }

.xt-action-4 + .xt-spacer {
    display: block !important; position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
    background-color: rgba(255, 249, 240, 0.85) !important; backdrop-filter: blur(4px) !important; 
    background-image: url('https://imgbed.heliar.top/i/Bp10UJSSMttc0Q3e_IMG_2564.png') !important; background-size: 100% 100% !important;
    z-index: 2000 !important; opacity: 0 !important; pointer-events: none !important; transform: scale(0.95) !important; transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}

.xt-text-secretThought {
    position: absolute !important; 
    top: 72% !important; left: 48% !important; width: 48% !important; height: auto !important; min-height: 15% !important; max-height: 35% !important;

    z-index: 2001 !important; opacity: 0 !important; pointer-events: none !important; transform: scale(0.95) !important; transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
    color: #4a362c !important; font-size: 16px !important; line-height: 1.8 !important; text-align: center !important; font-weight: bold !important;
    display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important;
    background: #fff !important; border: 4px solid #f29c9f !important; border-radius: 25px 20px 25px 20px !important; padding: 20px 15px !important; box-shadow: 0 8px 20px rgba(242, 156, 159, 0.3) !important; overflow-y: auto !important;
}
.xt-text-secretThought::-webkit-scrollbar { display: none !important; width: 0 !important; }

#xt-t4:checked ~ .xt-content .xt-action-4 + .xt-spacer, #xt-t4:checked ~ .xt-content .xt-text-secretThought { opacity: 1 !important; transform: scale(1) !important; }
#xt-t4:checked ~ .xt-content .xt-action-4 { top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2005 !important; background: transparent !important; }

/* =========================================
   📖 7. 彩蛋五：长条 Apple Sweets 剧情
   ========================================= */
.xt-action-5, .xt-action-6, .xt-action-7, .xt-action-8 {
    display: none !important; position: absolute !important; background: transparent !important; border: none !important; cursor: pointer !important;
}

.xt-action-5 {
    display: block !important; top: 20% !important; left: 78% !important; width: 18% !important; height: 32% !important; z-index: 1001 !important;
}
.xt-action-5:active { background: radial-gradient(ellipse at center, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0) 70%) !important; border-radius: 30px !important; }

.xt-action-8 + .xt-spacer {
    display: none !important; position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
    background-color: rgba(255, 249, 240, 0.85) !important; backdrop-filter: blur(4px) !important;
    background-image: url('https://imgbed.heliar.top/i/RkZ1sYV3NE304EFJ_IMG_2618.png') !important; background-size: 100% 100% !important;
    z-index: 2000 !important;
}

.xt-text-finalConfession {
    display: none !important; position: absolute !important; 
    top: 50% !important; 
    left: 3% !important; 
    width: 75% !important; 
    height: auto !important; min-height: 15% !important; max-height: 45% !important;

    z-index: 2001 !important; color: transparent !important; font-size: 18px !important; line-height: 1.8 !important; text-align: center !important; font-weight: bold !important;
    flex-direction: column !important; align-items: center !important; justify-content: center !important;
    background: #fff !important; border: 4px solid #f29c9f !important; border-radius: 25px 20px 25px 20px !important; padding: 25px 15px !important; box-shadow: 0 8px 20px rgba(242, 156, 159, 0.3) !important;
    transform-origin: center !important; transform: scale(0.95) !important; overflow-y: auto !important;
}
.xt-text-finalConfession::-webkit-scrollbar { display: none !important; width: 0 !important; }

.xt-text-finalConfession::before { content: "哎呀这里也被你发现啦"; color: #4a362c !important; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 90%; text-align: center; }

@keyframes popInBg { 0% { opacity: 0; transform: scale(0.95); } 100% { opacity: 1; transform: scale(1); } }
@keyframes popInText { 0% { opacity: 0; transform: scale(0.95); } 100% { opacity: 1; transform: scale(1); } }

#xt-t5:checked ~ .xt-content .xt-action-8 + .xt-spacer { display: block !important; animation: popInBg 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
#xt-t5:checked ~ .xt-content .xt-text-finalConfession { display: flex !important; animation: popInText 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }

#xt-t5:checked ~ .xt-content .xt-action-5 { display: none !important; } 
#xt-t5:checked ~ .xt-content .xt-action-6 { display: block !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2005 !important; }

#xt-t5:checked ~ #xt-t6:checked ~ .xt-content .xt-action-6 { display: none !important; }
#xt-t5:checked ~ #xt-t6:checked ~ .xt-content .xt-action-7 { display: block !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2006 !important; }

#xt-t5:checked ~ #xt-t7:checked ~ .xt-content .xt-action-7 { display: none !important; }
#xt-t5:checked ~ #xt-t7:checked ~ .xt-content .xt-action-8 { display: block !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2007 !important; }

#xt-t5:checked ~ #xt-t8:checked ~ .xt-content .xt-action-8 { display: none !important; }
#xt-t5:checked ~ #xt-t8:checked ~ .xt-content .xt-action-5 { display: block !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; z-index: 2008 !important; background: transparent !important; border-radius: 0 !important; }

#xt-t5:checked ~ #xt-t6:checked ~ .xt-content .xt-text-finalConfession::before { content: "不要再点了啦再点也没有东西啦"; }
#xt-t5:checked ~ #xt-t7:checked ~ .xt-content .xt-text-finalConfession::before { content: "你真的还想再试试吗🥺"; }
#xt-t5:checked ~ #xt-t8:checked ~ .xt-content .xt-text-finalConfession { color: #4a362c !important; }
#xt-t5:checked ~ #xt-t8:checked ~ .xt-content .xt-text-finalConfession::before { content: "都说了没有东西啦\A好吧…其实…"; white-space: pre-wrap; position: static !important; transform: none !important; margin-bottom: 5px !important; }

