  border:none!important;pointer-events:none!important;
}
.xt-collapse-7 .xt-collapse-arrow{display:none!important;}
.xt-collapse-7 .xt-collapse-body{
  max-height:9999px!important;overflow:visible!important;
  background:var(--wg)!important;padding:0!important;
}
/* wcName → 微信顶栏标题 */
.xt-text-wcName{
  background:#EDEDED!important;color:var(--tx)!important;
  font-size:16px!important;font-weight:500!important;
  text-align:center!important;padding:10px 44px!important;margin:0!important;
  border-bottom:.5px solid #D0D0D0!important;
  position:relative!important;
}
.xt-text-wcName::before{
  content:"❮"!important;position:absolute!important;left:14px!important;top:50%!important;
  transform:translateY(-50%)!important;font-size:16px!important;font-weight:400!important;color:var(--tx)!important;
}
.xt-text-wcName::after{
  content:"⋯"!important;position:absolute!important;right:14px!important;top:50%!important;
  transform:translateY(-50%)!important;font-size:18px!important;font-weight:700!important;color:var(--tx)!important;
}
/* 群聊消息 */
.xt-collapse-7 .xt-list{padding:8px 12px 12px!important;margin:0!important;}
.xt-collapse-7 .xt-list-check{display:none!important;}
.xt-collapse-7 .xt-list-item{
  display:block!important;position:relative!important;
  padding:4px 0!important;min-height:20px!important;
  border:none!important;
}
.xt-collapse-7 .xt-list-item::before{display:none!important;}
.xt-collapse-7 .xt-list-text{
  display:inline-block!important;
  background:var(--wgw)!important;color:var(--tx)!important;
  font-size:14px!important;line-height:1.55!important;
  padding:8px 12px!important;border-radius:4px!important;
  word-break:break-word!important;white-space:normal!important;
  max-width:82%!important;position:relative!important;
  box-shadow:0 .5px 1px rgba(0,0,0,.06)!important;
  margin-top:18px!important;
}
/* 气泡上方名字（用 ::before 在气泡外上方显示）*/
.xt-collapse-7 .xt-list-text::before{
  content:""!important;position:absolute!important;left:0!important;top:-16px!important;
  font-size:11px!important;font-weight:400!important;color:var(--tx3)!important;
  white-space:nowrap!important;
}
/* 气泡小三角 */
.xt-collapse-7 .xt-list-text::after{
  content:""!important;position:absolute!important;left:-5px!important;top:10px!important;
  width:0!important;height:0!important;
  border-top:5px solid transparent!important;border-bottom:5px solid transparent!important;
  border-right:5px solid var(--wgw)!important;
}
/* char 发言 = 第4、第8条 = 绿色右对齐 */
.xt-collapse-7 .xt-list-item:nth-child(4),
.xt-collapse-7 .xt-list-item:nth-child(8){
  text-align:right!important;
}
.xt-collapse-7 .xt-list-item:nth-child(4) .xt-list-text,
.xt-collapse-7 .xt-list-item:nth-child(8) .xt-list-text{
  background:var(--wgt)!important;color:#fff!important;
  text-align:left!important;
}
.xt-collapse-7 .xt-list-item:nth-child(4) .xt-list-text::before,
.xt-collapse-7 .xt-list-item:nth-child(8) .xt-list-text::before{
  left:auto!important;right:0!important;
}
.xt-collapse-7 .xt-list-item:nth-child(4) .xt-list-text::after,
.xt-collapse-7 .xt-list-item:nth-child(8) .xt-list-text::after{
  left:auto!important;right:-5px!important;
  border-right:none!important;border-left:5px solid var(--wgt)!important;
}

/* ═══════════════════════════════════════════
   TA的心声 collapse-8
   ═══════════════════════════════════════════ */
.xt-collapse-8{background:var(--wt)!important;border:none!important;border-top:8px solid var(--pg)!important;border-radius:0!important;margin:0!important;}
.xt-collapse-8 .xt-collapse-header{
  background:linear-gradient(90deg,rgba(251,114,153,.06),rgba(0,174,236,.03))!important;
  color:var(--bpd)!important;font-weight:700!important;font-size:15px!important;
  padding:14px!important;border-bottom:1px solid var(--ln)!important;
}
.xt-collapse-8 .xt-collapse-arrow{color:var(--bp)!important;}
.xt-collapse-8 .xt-collapse-body{background:var(--wt)!important;padding:14px!important;}
.xt-collapse-8 .xt-quote{
  background:rgba(251,114,153,.04)!important;
  border:1px solid rgba(251,114,153,.12)!important;
  border-radius:10px!important;color:var(--tx)!important;
  font-size:14.5px!important;line-height:1.95!important;
}
.xt-collapse-8 .xt-quote::before,.xt-collapse-8 .xt-quote::after{color:var(--bp)!important;opacity:.4!important;}
.xt-text-heartWord{
  text-align:center!important;color:var(--bpd)!important;
  font-weight:700!important;font-size:15px!important;
  background:none!important;margin-top:8px!important;padding:4px!important;
}
.xt-text-heartWord::before{content:"「"!important;color:var(--bp)!important;}
.xt-text-heartWord::after{content:"」"!important;color:var(--bp)!important;}

/* ═══════════════════════════════════════════
   通用 card
   ═══════════════════════════════════════════ */
.xt-card{
  background:var(--wt)!important;border:none!important;
  border-top:8px solid var(--pg)!important;border-radius:0!important;
  box-shadow:none!important;margin:0!important;padding:14px!important;
}
.xt-card-title{
  color:var(--tx)!important;font-weight:700!important;font-size:16px!important;
  border:none!important;padding:0 0 12px!important;
  border-bottom:1px solid var(--ln)!important;margin-bottom:0!important;
}

/* ═══════════════════════════════════════════
   微博热搜
   ═══════════════════════════════════════════ */
.xt-card .xt-list{padding:0!important;margin:0!important;counter-reset:rank!important;}
.xt-card .xt-list-item{
  display:flex!important;align-items:center!important;
  padding:14px 0!important;border-bottom:1px solid #F0F0F0!important;
  position:relative!important;counter-increment:rank!important;
}
.xt-card .xt-list-item:last-child{border-bottom:none!important;}
.xt-card .xt-list-check{display:none!important;}
.xt-card .xt-list-item::before{
  content:counter(rank)!important;
  min-width:28px!important;text-align:center!important;
  font-size:18px!important;font-weight:900!important;font-style:italic!important;
  margin-right:10px!important;flex-shrink:0!important;color:var(--tx3)!important;
}
.xt-card .xt-list-item:nth-child(1)::before{color:#FE2D46!important;font-size:20px!important;}
.xt-card .xt-list-item:nth-child(2)::before{color:#FF7A00!important;font-size:19px!important;}
.xt-card .xt-list-item:nth-child(3)::before{color:#FFB900!important;}
.xt-card .xt-list-text{flex:1!important;color:var(--tx)!important;font-size:14px!important;font-weight:500!important;line-height:1.5!important;word-break:break-word!important;}
.xt-card .xt-list-item:nth-child(1)::after{content:"热"!important;font-size:10px!important;font-weight:700!important;color:#fff!important;background:#FE2D46!important;padding:1px 5px!important;border-radius:3px!important;margin-left:8px!important;flex-shrink:0!important;}
.xt-card .xt-list-item:nth-child(3)::after{content:"新"!important;font-size:10px!important;font-weight:700!important;color:#fff!important;background:var(--bb)!important;padding:1px 5px!important;border-radius:3px!important;margin-left:8px!important;flex-shrink:0!important;}

/* ═══════════════════════════════════════════
   INS 高仿真
   ═══════════════════════════════════════════ */
.xt-text-insUser{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:13.5px!important;font-weight:700!important;
  padding:10px 14px 10px 52px!important;
  position:relative!important;border-bottom:.5px solid var(--ln)!important;
}
.xt-text-insUser::before{
  content:""!important;position:absolute!important;left:14px!important;top:8px!important;
  width:30px!important;height:30px!important;border-radius:50%!important;
  background:conic-gradient(from 180deg,#F58529,#DD2A7B,#8134AF,#515BD4,#F58529)!important;
}
.xt-text-insUser::after{
  content:"⋯"!important;position:absolute!important;right:14px!important;top:50%!important;
  transform:translateY(-50%)!important;font-size:16px!important;color:var(--tx)!important;font-weight:900!important;
}
.xt-text-insImg{
  position:relative!important;min-height:300px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  text-align:center!important;
  background:linear-gradient(165deg,#2c2c3a 0%,#1a1a28 35%,#2a2035 70%,#1c1826 100%)!important;
  color:rgba(255,255,255,.3)!important;font-size:13px!important;font-style:italic!important;
  line-height:1.9!important;letter-spacing:.3px!important;
  padding:30px 24px!important;margin:0!important;
  border:none!important;border-radius:0!important;
}
.xt-text-insImg::after{
  content:""!important;position:absolute!important;bottom:0!important;left:0!important;right:0!important;
  height:60px!important;background:linear-gradient(transparent,rgba(0,0,0,.2))!important;pointer-events:none!important;
}
/* 操作栏 ♡ 💬 ✈ ... ⚑ */
.xt-text-insCaption{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:14px!important;line-height:1.65!important;
  padding:0 14px 8px!important;margin:0!important;
  position:relative!important;padding-top:46px!important;
}
.xt-text-insCaption::before{
  content:"♡    💬    ✈"!important;
  position:absolute!important;top:10px!important;left:14px!important;
  font-size:22px!important;color:var(--tx)!important;letter-spacing:2px!important;
}
.xt-text-insCaption::after{
  content:"⚑"!important;
  position:absolute!important;top:10px!important;right:14px!important;
  font-size:22px!important;color:var(--tx)!important;
}
.xt-text-insLike{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:13.5px!important;font-weight:700!important;
  padding:0 14px 6px!important;
}
.xt-text-insLike::after{content:" likes"!important;font-weight:400!important;color:var(--tx2)!important;}
.xt-text-insTime{
  background:var(--wt)!important;color:var(--tx3)!important;
  font-size:10px!important;padding:0 14px 10px!important;
  text-transform:uppercase!important;letter-spacing:.5px!important;
  border-bottom:.5px solid var(--ln)!important;
}
.xt-text-insCmt1,.xt-text-insCmt2,.xt-text-insCmt3{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:13px!important;line-height:1.5!important;
  padding:5px 14px!important;
}
.xt-text-insCmt1{padding-top:10px!important;}
.xt-text-insCmt3::after{
  content:"查看全部 89 条评论"!important;
  display:block!important;margin-top:8px!important;
  font-size:12px!important;color:var(--tx3)!important;font-weight:400!important;
}

/* ═══════════════════════════════════════════
   下期预告
   ═══════════════════════════════════════════ */
.xt-text-nextEp{
  background:none!important;border:none!important;color:var(--tx)!important;
  font-size:14.5px!important;line-height:1.85!important;padding:6px 0 8px 10px!important;margin:0!important;
  border-left:3px solid var(--bp)!important;
}
.xt-text-nextHint{
  background:linear-gradient(135deg,rgba(251,114,153,.04),rgba(0,174,236,.06))!important;
  border:1px dashed rgba(0,174,236,.2)!important;
  border-radius:10px!important;color:var(--tx2)!important;
  font-size:13px!important;font-style:italic!important;line-height:1.7!important;
  padding:12px 14px!important;margin:8px 0 0!important;
}
.xt-text-nextHint::before{content:"🎬 "!important;font-style:normal!important;}
.xt-text-nextHint::after{content:" ……"!important;color:var(--bb)!important;font-style:normal!important;}

/* ═══════════════════════════════════════════
   片尾曲
   ═══════════════════════════════════════════ */
.xt-text-edSong{
  background:none!important;border:none!important;color:var(--tx)!important;
  font-size:15px!important;font-weight:700!important;padding:6px 0 8px 28px!important;margin:0!important;
  position:relative!important;
}
.xt-text-edSong::before{
  content:"♫"!important;position:absolute!important;left:0!important;top:6px!important;
  color:var(--bp)!important;font-size:18px!important;
}
.xt-text-edSong::after{
  content:"━━━━━━━━━━━━━ ▶ ━━"!important;
  display:block!important;margin-top:8px!important;
  font-size:10px!important;color:var(--tx3)!important;letter-spacing:1px!important;
  opacity:.5!important;
}
.xt-quote{
  background:rgba(251,114,153,.04)!important;
  border:1px solid rgba(251,114,153,.12)!important;
  border-radius:10px!important;color:var(--tx2)!important;
  font-size:14px!important;line-height:1.95!important;font-style:italic!important;
}
.xt-quote::before,.xt-quote::after{color:var(--bp)!important;opacity:.35!important;}

/* ═══════════════════════════════════════════
   底部
   ═══════════════════════════════════════════ */
.xt-footer{color:var(--tx3)!important;letter-spacing:1px!important;margin-top:12px!important;font-size:11px!important;padding:0 14px!important;}

