_theme.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

/*⁣​‌​​‍⁠‍‌​​‍​‌​‌‍‌​‍‍⁠​⁠‍‌​⁠​⁠​‌‌‍‌⁠‌⁠‌​⁠‌‍⁠‌‍​⁠​‌⁠‍⁠⁠‍‍​⁠‍⁠‌‌​‌⁠⁣ ══════════════════════
   ROOT
══════════════════════ */
.xt-root {
  --xt-bg:         #fffdf6;
  --xt-text:       #4a3020;
  --xt-text-sub:   #9a7868;
  --xt-text-muted: #c8b0a0;
  --xt-accent:     #7dbfa0;
  --xt-accent-bg:  rgba(125,191,160,0.12);
  --xt-border:     #e8d8c8;
  --xt-radius:     18px;
  --xt-radius-sm:  11px;
  --xt-font:       'Noto Sans SC','PingFang SC','Hiragino Sans GB',sans-serif;
  --xt-anim-duration: 0.28s;
  --pink:          #e8808a;
  --pink-bg:       #fff5f5;
  --pink-border:   #f5c8cc;
  --pink-text:     #b03848;
  background: var(--xt-bg);
  padding: 0;
  font-size: 13px;
  line-height: 1.5;
}
.xt-content { padding: 14px 13px 14px; }

/* ══════════════════════
   CARD 通用
══════════════════════ */
.xt-card {
  background: #fff !important;
  border: 1.5px solid #ecddd0 !important;
  border-radius: 16px !important;
  padding: 0 !important;
  margin-bottom: 10px !important;
  box-shadow: 0 2px 12px rgba(212,236,223,0.45) !important;
  overflow: hidden !important;
}
.xt-card:hover { box-shadow: 0 4px 18px rgba(125,191,160,0.22) !important; transform: none !important; }
.xt-card-title {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #c8b0a0 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  padding: 11px 14px 2px !important;
  margin: 0 !important;
  display: block !important;
}

/* ══════════════════════
   最近搜索区
   设计：带标题的独立白卡
   四行搜索词 + 展开心声
══════════════════════ */

/* 四个搜索词共同外包一个白卡效果
   用 search1 第一行的 ::before 做卡片标题 */
.xt-text-search1 {
  margin-top: 0 !important;
  border-radius: 16px 16px 0 0 !important;
  border-bottom: 1px solid #faf3ee !important;
  padding-top: 10px !important;
}
.xt-text-search1::before {
  content: "🔍  最近搜索" !important;
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #c8b0a0 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  margin-bottom: 8px !important;
