#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body > *:nth-child(2) { animation-delay: .12s; }
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body > *:nth-child(3) { animation-delay: .24s; }
