#xt-t4:checked ~ .xt-content .xt-action-4 { transform: translateY(-3px); color: #3f3f47; }
#xt-t4:checked ~ .xt-content .xt-action-4::after { background: #4a4a52; color: #fff; transform: rotate(180deg); }
