/* ───────── 折叠面板（由图片按钮驱动，标题行隐藏） ───────── */
.xt-collapse { border: none !important; background: none !important; margin: 0 !important; padding: 0 !important; box-shadow: none !important; }
.xt-collapse-header { display: none !important; }
.xt-collapse-body {
  max-height: 0 !important;
  opacity: 0;
  overflow: hidden;
  padding: 0 !important;
  background: none !important;
  transition: max-height .9s cubic-bezier(.22,.8,.3,1), opacity .6s ease;
}
@keyframes xtRise {
  from { opacity: 0; transform: translateY(12px); filter: blur(4px); }
  to   { opacity: 1; transform: none; filter: blur(0); }
}
#xt-t1:checked ~ .xt-content .xt-action-1 { transform: translateY(-3px); color: #3f3f47; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { background: #4a4a52; color: #fff; transform: rotate(180deg); }
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body { max-height: 3000px !important; opacity: 1; }
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body > * { animation: xtRise .8s cubic-bezier(.22,.8,.3,1) both; }
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body > *:nth-child(2) { animation-delay: .12s; }
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body > *:nth-child(3) { animation-delay: .24s; }
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body > *:nth-child(4) { animation-delay: .36s; }
