_theme.customCss:
/*⁣​‌​​‍⁠‍‌​​‍​‌​‌‍‌​‍‍⁠​⁠‍‌​⁠​⁠​‌‌‍‌⁠‌⁠‌​⁠‌‍⁠‌‍​⁠​‌⁠‍⁠⁠‍‍​⁠‍⁠‌‌​‌⁠⁣ 0. 彻底重置 */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: 'Courier New', Courier, -apple-system, BlinkMacSystemFont, sans-serif !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* ================= 1. 根容器 主底色：极浅红调白 ================= */
.xt-root {
    width: 360px !important; height: 680px !important;
    background: #F8E8E9 !important;
    border-radius: 24px !important; 
    position: relative !important; margin: 20px auto !important;
    overflow: hidden !important; pointer-events: auto !important;
}

/* 1. 背景纹理 */
.xt-text:nth-of-type(1) {
    position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
